describe('Login Form CAPTCHA', () => {
    beforeEach(() => {
        cy.visit('/login');
    });

    it('should display CAPTCHA after 3 failed login attempts', () => {
        for (let i = 0; i < 3; i++) {
            cy.get('input[name="username"]').type('invalidUser');
            cy.get('input[name="password"]').type('invalidPass');
            cy.get('button[type="submit"]').click();
            cy.get('.error-message').should('be.visible').and('contain', 'Invalid credentials');
        }
        cy.get('.captcha').should('be.visible');
    });

    it('should not display CAPTCHA if login is successful before 3 attempts', () => {
        cy.get('input[name="username"]').type('validUser');
        cy.get('input[name="password"]').type('validPass');
        cy.get('button[type="submit"]').click();
        cy.url().should('include', '/dashboard');
        cy.get('.captcha').should('not.exist');
    });
});
